# -*- coding: utf-8 -*-
"""Этапы 4 и 5: разделы реестра «Научные материалы» и «Эмпирические материалы», перечень по разделам, контрольные суммы."""
import os, re, sys, json, hashlib, collections
HERE = os.path.dirname(os.path.abspath(__file__))
import sci_place as P
import lit_place as LP
mb = LP.mb
NOQ = {'g': [], 's': ['незаконный доступ сотрудников к базам данных и разглашение сведений', 'меры безопасности в отношении защищаемых лиц', 'заведомо ложный донос в отношении сотрудника полиции', 'тактика задержания взяткополучателя']}
def esc(s): return s.replace('|', '-')
def link(u, label):
    return '[%s](%s)' % (label, u.replace(' ', '%20').replace('(', '%28').replace(')', '%29')) if u.startswith('http') else label
def secs(p): return 'все' if p == ['*'] else ', '.join(p)
def nwords(n, a, b, c):
    return a if n % 10 == 1 and n % 100 != 11 else b if n % 10 in (2, 3, 4) and n % 100 not in (12, 13, 14) else c
def registry():
    man = json.load(open(P.MAN, encoding='utf-8'))
    rej = [l.rstrip('\n').split('\t') for l in open(os.path.join(HERE, 'sci_rejected.tsv'), encoding='utf-8') if not l.startswith('#')]
    fails = json.load(open(os.path.join(HERE, 'sci_fail.json'), encoding='utf-8')) if os.path.exists(os.path.join(HERE, 'sci_fail.json')) else {}
    for d in 'gs':
        D = P.DISC[d]; root = os.path.join(P.ROOT, D, '2. Источники')
        mine = [m for m in man if m[d]]
        for m in mine:
            if not os.path.exists(os.path.join(P.ROOT, D, P.FOLDER[m['cat']], m['name'])): print('НЕТ ФАЙЛА:', d, m['name'][:70])
        sci = sorted([m for m in mine if m['cat'] == 'sci'], key=lambda m: (m['kind'] == 'журнал', m['name'].lower()))
        art = sorted([m for m in mine if m['cat'] == 'art'], key=lambda m: m['name'].lower())
        emp = sorted([m for m in mine if m['cat'] == 'emp'], key=lambda m: m['name'].lower())
        lit = [m for m in mine if m['cat'] == 'lit']
        sel = json.load(open(os.path.join(HERE, 'cyber_%s_selected.json' % d), encoding='utf-8'))
        nq = sum(1 for l in open(os.path.join(HERE, 'cyber_q_%s.txt' % d), encoding='utf-8') if l.strip() and not l.startswith('#'))
        nrows = sum(1 for l in open(os.path.join(HERE, 'cyber_%s.tsv' % d), encoding='utf-8') if l.strip())
        ay = collections.Counter(m['year'] for m in art); kinds = collections.Counter('журналы' if m['kind'] == 'журнал' else 'монографии и иные авторские научные издания' if m['authors'] else 'сборники научных трудов и материалов конференций' for m in sci)
        o = ['<!-- SCI-BEGIN -->', '## Научные материалы (этап 4 сбора источников)', '']
        o.append('Состояние на %s. В папке `4. Научные материалы (с 2023 года)` — **%d %s 2023–2026 годов** (%s; %s) и **%d %s из научных журналов** в подпапке `Статьи` (%s; из них %d — из журналов перечня ВАК по отметке cyberleninka.ru). '
                 'Статьи по годам: %s. Подпапка `Издания до 2023 года (сверить с действующими актами)` пуста: изданий старше 2023 года не бралось.'
                 % (P.TODAY, len(sci), nwords(len(sci), 'издание', 'издания', 'изданий'), mb(sum(m['size'] for m in sci)), ', '.join('%s — %d' % kv for kv in kinds.most_common()),
                    len(art), nwords(len(art), 'статья', 'статьи', 'статей'), mb(sum(m['size'] for m in art)), sum(1 for m in art if m.get('vak')), ', '.join('%d — %d' % (y, ay[y]) for y in sorted(ay))))
        o += ['', 'Откуда взято. Издания — из открытых каталогов электронной библиотеки lib.eioskuimvd.ru: это %d научных и аналитических изданий, отложенных на этапе 3; после просмотра титульных листов и подсчёта тематических слов по всему тексту в базы двух дисциплин взято %d, не взято %d (раздел НМ.3). '
                    'Статьи — с cyberleninka.ru: по разделам перечня вопросов составлено %d поисковых запросов, поиск вернул %d записей 2023–2026 годов, программный отбор по названию и аннотации оставил %d, загружено и проверено %d.'
                    % (len(P.DEC) + len(P.REJ), len(P.DEC), len(P.REJ), nq, nrows, len(sel), len(art))]
        o += ['', 'Год издания проверен по тексту титульного листа; названия, авторы и выходные данные изданий внесены вручную по титульным листам. Столбец «Разделы» — номера разделов перечня вопросов (их названия — в файле `4. Научные материалы (с 2023 года)/Научные материалы по разделам перечня.md`); «все» — издание по предмету дисциплины в целом.']
        o += ['', '### НМ.1. Издания', '', '| Файл | Что это | Год | Стр. | Размер | Откуда | Разделы |', '|---|---|---|---|---|---|---|']
        for m in sci: o.append('| %s | %s | %s | %s | %s | %s | %s |' % (esc(m['name']), esc(m['what']), m['year'], m['pages'], mb(m['size']), link(m['url'], 'библиотека'), secs(m[d])))
        o += ['', '### НМ.2. Статьи', '', 'Файлы лежат в подпапке `Статьи`. Имя файла: авторы, название (длинное сокращено), журнал, год. «ВАК» — отметка cyberleninka.ru о журнале из перечня ВАК.', '',
              '| Файл | Стр. | ВАК | Разделы | Источник |', '|---|---|---|---|---|']
        for m in art: o.append('| %s | %s | %s | %s | %s |' % (esc(m['name']), m['pages'], 'да' if m.get('vak') else '', secs(m[d]), link(m['url'], 'cyberleninka')))
        o += ['', '### НМ.3. Чего нет и почему', '']
        o.append('- Издания и статьи старше 2023 года — не брались по условию этапа.')
        o.append('- Диссертации и авторефераты — не искались.')
        o.append('- Статьи, которых нет на cyberleninka.ru (elibrary.ru, платные журналы), — не искались: загрузчику доступен только этот открытый архив.')
        f = fails.get(d, {})
        if f.get('fail'): o.append('- Отобрано, но не загружено или отбраковано после загрузки — %d %s из %d: %s. Список — `.github/downloader/books/sci_fail.json`.' % (f['fail'], nwords(f['fail'], 'статья', 'статьи', 'статей'), len(sel), f.get('why', '')))
        if NOQ[d]: o.append('- По запросам %s подходящих статей 2023 года и новее не нашлось.' % '; '.join('«%s»' % q for q in NOQ[d]))
        cnt = collections.Counter(p for m in art for p in m[d]); weak = [n for n, _ in P.PARTS[d] if cnt[n] < 10]
        if weak: o.append('- Меньше десяти статей — по разделам %s.' % ', '.join(weak))
        rc = collections.Counter(re.sub(r':.*', '', r[0]) for r in rej)
        o.append('- Издания библиотеки, загруженные и не взятые после просмотра, — %d (на обе дисциплины): %s. Список с причинами — `.github/downloader/books/sci_rejected.tsv`.' % (len(rej), '; '.join('%s — %d' % kv for kv in rc.most_common())))
        o.append('- 18 изданий библиотеки объёмом свыше 99 МБ не просматривались и не брались: GitHub не принимает файлы больше 100 МБ.')
        if d == 'g': o.append('- Монографий 2023 года и новее именно о деятельности Госавтоинспекции в открытой библиотеке не нашлось: предмет закрыт журналами и обзорами Научного центра БДД МВД России, сборниками конференций и статьями.')
        else: o.append('- Монографий и сборников 2023 года и новее именно о подразделениях собственной безопасности в открытой библиотеке нет: взяты издания по смежным предметам — противодействие коррупции, оперативно-розыскная деятельность, досудебное производство, служебная дисциплина и ответственность сотрудников, личная безопасность, защита информации.')
        o += ['', '### НМ.4. Что проверить и какие оговорки нужны', '']
        o.append('- Статьи отобраны программно по названию и аннотации; полные тексты не читались. Названия просмотрены глазами лишь частично, поэтому среди статей возможны нерелевантные. Перед ссылкой на статью её нужно открыть.')
        o.append('- Привязка к разделам перечня сделана по поисковому запросу (статьи) и по названию с подсчётом тематических слов в тексте (издания) — не к отдельным вопросам.')
        o.append('- Сборники конференций и журналы взяты целиком: в каждом к дисциплине относится только часть статей.')
        o.append('- Соответствие материалов действующему законодательству не проверялось: публикации 2023–2024 годов могут не учитывать изменения 2025–2026 годов. Нормы сверять с актами папки `1. Нормативные правовые акты`.')
        o.append('- Отметка «ВАК» взята с cyberleninka.ru и отражает состояние на дату поиска; по действующему перечню ВАК она не перепроверялась.')
        o.append('- Номер журнала «Современная наука» № 4 за 2024 год определён по адресу файла в библиотеке: в тексте файла год не указан.')
        if lit: o.append('- %d учебных и методических издания Научного центра БДД МВД России и Орловского юридического института, оказавшиеся среди отложенных, положены в папку `3. Учебная литература/1. Профильные издания` и внесены в раздел «Учебная литература».' % len(lit))
        o += ['', '<!-- SCI-END -->', '', '<!-- EMP-BEGIN -->', '## Эмпирические материалы (этап 5 сбора источников)', '']
        new = [m for m in emp if m['key'].startswith('emp:') and m['url']]; lib = [m for m in emp if not m['key'].startswith('emp:')]; old = [m for m in emp if m['key'].startswith('emp:') and not m['url']]
        o.append('Состояние на %s. В папке `5. Эмпирические материалы (с 2023 года)` — **%d %s** (%s): %d загружено на этом этапе, %d — аналитические издания из электронной библиотеки, %d скопировано из баз других дисциплин этого хранилища (те же файлы, побайтно).'
                 % (P.TODAY, len(emp), nwords(len(emp), 'источник', 'источника', 'источников'), mb(sum(m['size'] for m in emp)), len(new), len(lib), len(old)))
        o += ['', '| Файл | Что это | Стр. | Размер | Откуда | Разделы |', '|---|---|---|---|---|---|']
        for m in emp:
            src = link(m['url'], 'библиотека' if m['origin'] == P.LIBNOTE else m['origin']) if m['url'] else m['origin']
            o.append('| %s | %s | %s | %s | %s | %s |' % (esc(m['name']), esc(m['what']), m['pages'] or '—', mb(m['size']), src, secs(m[d])))
        o += ['', '### ЭМ.1. Чего нет и почему', '']
        ef = fails.get('emp', {})
        if d == 'g':
            if not ef.get('dtp2025.pdf'): o.append('- Обзор Научного центра БДД «Дорожно-транспортная аварийность в Российской Федерации в 2025 году» издан (2026), но открытого адреса файла найти не удалось; предполагаемый адрес ответил ошибкой. Данные за 2025 год по преступлениям есть в сборнике ГИАЦ, по наказаниям — в форме № 1-АП.')
            o.append('- Сведения Госавтоинспекции о показателях аварийности размещены на stat.gibdd.ru, обзоры МВД России — на мвд.рф; загрузчику эти сайты недоступны (соединение не устанавливается).')
            o.append('- Обзор «Правоприменительная деятельность в области безопасности дорожного движения» за 2023 год известен по ссылкам в литературе, файла в открытом доступе не найдено; в базе выпуск за 2024 год.')
            o.append('- Ведомственная статистика о работе нарядов ДПС, применении физической силы, специальных средств и оружия, о регистрационной и экзаменационной работе — в открытом доступе не публикуется.')
        else:
            o.append('- Статистика подразделений собственной безопасности МВД России (выявленные преступления и нарушения сотрудников, результаты служебных проверок, применение государственной защиты) — в открытом доступе не публикуется; сведения встречаются только в отдельных выступлениях и статьях.')
            o.append('- Раздел сайта Судебного департамента «Данные судебной статистики по делам коррупционной направленности» закрыт для посетителей без учётной записи.' + (' Форма № 10.4.1 получена по прямому адресу файла только за %s.' % ', '.join(ef['f1041']) if ef.get('f1041') else ' Формы № 10.4.1 по прямым адресам получить не удалось. Число осужденных по статьям 285, 286, 290–291.2, 292, 293 УК РФ есть в форме № 10-а «Судимость».'))
            o.append('- Доклады Генеральной прокуратуры РФ и Национальный план противодействия коррупции как статистический источник не брались: план — нормативный акт (папка 1), сводных открытых докладов с цифрами по органам внутренних дел нет.')
        o.append('- Сборник ГИАЦ «Состояние преступности» за 2023 год не найден; данные за 2023 год есть в обзоре ВНИИ МВД России.')
        o.append('- Обзор судебной статистики Судебного департамента за 2025 год по предполагаемому адресу не найден (ошибка 404).')
        o.append('- Доклады Уполномоченного по правам человека в РФ — не взяты: файлы за 2023 и 2025 годы больше 98 МБ, доклад за 2024 год (83 МБ) есть в базе «Административная деятельность полиции».')
        o += ['', '### ЭМ.2. Что проверить и какие оговорки нужны', '']
        o.append('- Таблицы Судебного департамента (xls) — отчётные формы по всей стране; цифры по нужной статье нужно искать в строках формы. Содержание таблиц не проверялось, проверен только тип файла.')
        o.append('- Сборники ГИАЦ взяты не с сайта МВД России, а с копии на сайте вуза (portal.tpu.ru), обзоры Научного центра БДД — с копий на opis-cdn.tinkoffjournal.ru. Титульные листы проверены, с первоисточником файлы не сверялись.')
        o.append('- Данные за 2025 год приводить как данные за 2025 год: статистики за 2026 год в базе нет.')
        o += ['', '<!-- EMP-END -->']
        block = '\n'.join(o)
        rp = os.path.join(root, 'Реестр источников.md'); txt = open(rp, encoding='utf-8').read()
        if '<!-- SCI-BEGIN -->' in txt: txt = re.sub(r'<!-- SCI-BEGIN -->.*?<!-- EMP-END -->', lambda _: block, txt, flags=re.S)
        else: txt = txt.replace('<!-- LIT-END -->', '<!-- LIT-END -->\n\n' + block, 1)
        lines = txt.split('\n')
        nq_total = re.search(r'перечень из (\d+) вопросов', lines[2]).group(1)
        lines[2] = ('Состояние на %s: перечень из %s вопросов составлен; пройдены пять этапов сбора источников — нормативные правовые акты (раздел А), судебная практика, учебная литература 2023 года и новее, '
                    'научные материалы 2023 года и новее и эмпирические материалы (разделы с этими названиями идут один за другим после раздела А).' % (P.TODAY, nq_total))
        open(rp + '.tmp', 'w', encoding='utf-8').write('\n'.join(lines)); os.replace(rp + '.tmp', rp)
        # --- по разделам
        q = ['# Научные материалы по разделам перечня вопросов — ' + D, '', 'Состояние на %s. Издания и статьи папки `4. Научные материалы (с 2023 года)` разнесены по разделам перечня вопросов: статьи — по поисковому запросу, по которому найдены, издания — по названию и тематическим словам в тексте. '
             'Привязка сделана к разделам, а не к отдельным вопросам; тексты целиком не читались. Одна статья может стоять в нескольких разделах.' % P.TODAY, '']
        allp = [m for m in sci if m[d] == ['*']]
        for n, title in P.PARTS[d]:
            q += ['## Раздел %s. %s' % (n, title), '']
            a = [m for m in sci if n in m[d]]; b = [m for m in art if n in m[d]]; e = [m for m in emp if n in m[d]]
            if a: q += ['Издания:', ''] + ['- `%s`' % m['name'] for m in a] + ['']
            if b: q += ['Статьи (%d):' % len(b), ''] + ['- `Статьи/%s`' % m['name'] for m in b] + ['']
            if e: q += ['Эмпирические материалы (папка 5):', ''] + ['- `%s`' % m['name'] for m in e] + ['']
            if not (a or b or e): q += ['Отдельных материалов нет — см. издания ко всем разделам в конце файла.', '']
        if allp: q += ['## Издания ко всем разделам', ''] + ['- `%s`' % m['name'] for m in allp] + ['']
        qp = os.path.join(P.ROOT, D, P.D4, 'Научные материалы по разделам перечня.md'); open(qp, 'w', encoding='utf-8').write('\n'.join(q))
        # --- контрольные суммы
        sums = []
        for dp, dn, fn in os.walk(root):
            for f in fn:
                if f in ('Контрольные суммы SHA-256.txt', '.gitkeep'): continue
                full = os.path.join(dp, f); sums.append((os.path.relpath(full, root), LP.sha(full)))
        sums.sort()
        open(os.path.join(root, 'Контрольные суммы SHA-256.txt'), 'w', encoding='utf-8').write(''.join('%s  %s\n' % (h, p) for p, h in sums))
        print('%s: изданий %d, статей %d (ВАК %d), эмпирических %d, в папку 3 — %d; по разделам статей: %s; файлов в контрольных суммах %d'
              % (d, len(sci), len(art), sum(1 for m in art if m.get('vak')), len(emp), len(lit), ' '.join('%s:%d' % (n, cnt[n]) for n, _ in P.PARTS[d]), len(sums)))
if __name__ == '__main__': registry()
